using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using Mewgic;using Mewgic.Map;
public static class Part13JUiSelection{
static MapWorld Map=>UnityEngine.Object.FindFirstObjectByType<MapWorld>();
public static object Open(){Map.FocusRegion(11,false);Map.OpenChapter(11,4);return new{chapter=Map.SelectedChapter};}
public static object Select(){var p=Map.Points.Single(x=>x.kind==MapPointKind.LevelSlot&&x.slotIndex==49);p.GetComponent<Button>().onClick.Invoke();return new{clickedLevel=Map.Progression.LevelId(p.regionIndex,p.slotIndex)};}
public static object Return(){if(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name!="Gameplay"||GameplayLevelCatalog.SelectedId!=600)throw new Exception("Gercek600 acilmadi");GameObject.Find("Home").GetComponent<Button>().onClick.Invoke();return new{realGameplayOpened=600};}
public static object Verify(){if(Map==null||!Map.Mounted||Map.Progression.CurrentId!=600)throw new Exception("Harita/kayit bozuldu");var qa=UnityEngine.Object.FindFirstObjectByType<Part13JProbe>();var original=(System.Collections.Generic.Dictionary<string,string>)typeof(Part13JProbe).GetField("player",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(qa);bool intact=original.All(p=>p.Value==null?!PlayerPrefs.HasKey(p.Key):PlayerPrefs.GetString(p.Key)==p.Value);if(!intact)throw new Exception("Asil oyuncu kaydi degisti");var r=new{success=true,clickedActualLevelSlot=600,openedGameplay=600,returnedScene="LevelMap",currentId=Map.Progression.CurrentId,playerSaveAndBackupIntact=intact};string json=(string)Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new object[]{r});File.WriteAllText("docs/ProductionReports/Part13J/UI_SELECTION.json",json);return r;}}
